// ⭐ D105 P4 · ADMIN → DATA → ATLAS — the curator's minimal list, so the owner can publish the first pages.
//
// Every node is seeded as a DRAFT (D17: nothing generated by a model) and a public reader sees PUBLISHED pages only,
// so until someone publishes, /atlas is empty. This panel lists the nodes (drafts first by default), sorted by how
// many active postings ask for each — D105's first published set is "the roles the board has most postings for, then
// their top 20 skills each" — with Publish / Unpublish per row and "Recompute On the board".
//   GET  /api/admin/atlas?status=draft|published     POST /api/admin/atlas/:slug/status { status }
//   POST /api/admin/atlas/stats
// ⭐ D105 P6 · THE EDITOR (routes/atlas.js, admin only): Add a node (kind, name, a definition in draft's words — D17, no
// model), Merge two (the loser's edges and resources move; its term becomes a CONFIRMED alias in skill_synonyms, the one
// thesaurus), and per node: the definition and Wikipedia title, typed edges (never alias_of), resources (https only,
// title, level, format, hours, cost), "Check links now" (the daily dead-link checker) and "Refresh Wikipedia".
// ⭐ D105 P7 (amended 10-31) · THE ATLAS PUBLISHES ITSELF: a draft is published nightly once ≥ 5 active postings ask for
// it AND it has a Wikipedia summary or a definition. Each draft row says why it is not published yet (readinessLine:
// "postings 2 of 5 · no Wikipedia summary or definition"), a node a person unpublished says so and stays a draft, and
// "Run auto-publish now" runs the nightly titles → Wikidata → Wikipedia → bar pass (POST /api/admin/atlas/auto/run).
import { useCallback, useEffect, useMemo, useState } from "react";
import { api } from "../lib/api.js";
import { C } from "../styles/colorTokens.js";
import DepthButton from "../components/DepthButton.jsx";
import { Panel, Mark, row, quiet, sub, callout, field, useConfirm } from "./adminKit.jsx";

const KINDS = [["", "All kinds"], ["role", "Roles"], ["skill", "Skills"], ["tool", "Tools"], ["stack", "Stacks"]];
const NODE_KINDS = ["role", "skill", "tool", "stack"];
const EDGE_TYPES = [["requires", "requires"], ["part_of", "part of"], ["used_with", "used with"], ["alternative_to", "alternative to"], ["leads_to", "leads to"]];
const LEVELS = ["", "beginner", "intermediate", "advanced"];
const FORMATS = ["", "course", "docs", "book", "video", "tutorial", "article", "practice"];
const COSTS = ["", "free", "freemium", "paid"];
const STATUS_TONE = { ok: C.SUCCESS, failing: C.WARNING, dead: C.DANGER };
const enc = encodeURIComponent;
const send = (path, body, method = "POST") => api(path, { method, body: JSON.stringify(body || {}) });
const label = { display: "flex", flexDirection: "column", gap: 3, fontSize: 11, color: C.INK_MUTED };

/** Why a row is (not) published — from the server's readiness (services/atlas/atlasPublish.js readiness). */
function readinessLine(r) {
  const rd = r?.readiness;
  if (!rd) return null;
  if (r.status === "published") {
    const auto = r.publishedBy === "atlas-auto" ? "published automatically" : r.publishedBy ? `published by ${r.publishedBy}` : "published";
    return rd.postings < rd.need ? `${auto} · few open postings (${rd.postings} of ${rd.need}) — stays published` : auto;
  }
  if (rd.heldBy) return `unpublished by ${rd.heldBy} — auto-publish leaves it a draft until someone publishes it`;
  if (rd.ready) return "meets the bar — published at the next nightly check (or Run auto-publish now)";
  return `not published yet: ${rd.missing.join(" · ")}`;
}

/** Add a node by hand — a DRAFT until it is published. */
function AtlasAddNode({ onAdded, say }) {
  const [kind, setKind] = useState("skill");
  const [name, setName] = useState("");
  const [definition, setDefinition] = useState("");
  const [busy, setBusy] = useState(false);
  const add = async () => {
    setBusy(true);
    try {
      const r = await send("/api/admin/atlas/nodes", { kind, name, definition });
      say({ ok: true, text: `${r.node.name} added as a draft (/atlas/${r.node.slug} once published).` });
      setName(""); setDefinition(""); onAdded?.(r.node);
    } catch (e) { say({ ok: false, text: e.message }); }
    finally { setBusy(false); }
  };
  return (
    <div data-atlas-add="" style={{ ...sub, display: "grid", gap: 8 }}>
      <b style={{ fontSize: 13, color: C.INK }}>Add a node</b>
      <div style={row}>
        <select aria-label="New node's kind" value={kind} onChange={e => setKind(e.target.value)} style={field}>
          {NODE_KINDS.map(k => <option key={k} value={k}>{k}</option>)}
        </select>
        <input aria-label="New node's name" placeholder="Name (e.g. Kubernetes)" value={name} onChange={e => setName(e.target.value)} style={{ ...field, flex: "1 1 200px" }} />
      </div>
      <textarea aria-label="New node's definition" rows={2} placeholder="Definition — in draft's own words" value={definition}
        onChange={e => setDefinition(e.target.value)} style={{ ...field, height: "auto", padding: 8 }} />
      <div><DepthButton size="compact" primary disabled={busy || !name.trim()} onClick={add} data-atlas-add-go="">Add as a draft</DepthButton></div>
    </div>
  );
}

/** Merge two nodes: the loser's edges, resources and term move to the winner (its term a confirmed alias). */
function AtlasMerge({ onMerged, say }) {
  const [winner, setWinner] = useState("");
  const [loser, setLoser] = useState("");
  const [busy, setBusy] = useState(false);
  const { ask, dialog } = useConfirm();
  const merge = async () => {
    const ok = await ask({ title: "Merge two Atlas nodes", label: "Merge",
      body: <p style={{ margin: 0 }}><b>{loser}</b> is deleted. Its edges and resources move to <b>{winner}</b>, and its term becomes a confirmed alias of it in the scorer's thesaurus — which changes ATS scores (re-measure ρ after a batch, A76).</p> });
    if (!ok) return;
    setBusy(true);
    try {
      const r = await send("/api/admin/atlas/merge", { winner: winner.trim(), loser: loser.trim() });
      say({ ok: true, text: `Merged ${r.loser} into ${r.winner}: ${r.edgesMoved} edge(s), ${r.resourcesMoved} resource(s) moved; alias ${r.aliases.join(", ") || "—"}.` });
      setLoser(""); onMerged?.(r);
    } catch (e) { say({ ok: false, text: e.message }); }
    finally { setBusy(false); }
  };
  return (
    <div data-atlas-merge="" style={{ ...sub, display: "grid", gap: 8 }}>
      <b style={{ fontSize: 13, color: C.INK }}>Merge two nodes</b>
      <div style={row}>
        <input aria-label="Keep this node (slug)" placeholder="Keep (slug, e.g. kubernetes)" value={winner} onChange={e => setWinner(e.target.value)} style={{ ...field, flex: "1 1 160px" }} />
        <input aria-label="Merge this node into it (slug)" placeholder="Merge in and delete (slug, e.g. k8s)" value={loser} onChange={e => setLoser(e.target.value)} style={{ ...field, flex: "1 1 160px" }} />
        <DepthButton size="compact" disabled={busy || !winner.trim() || !loser.trim() || winner.trim() === loser.trim()} onClick={merge} data-atlas-merge-go="">Merge</DepthButton>
      </div>
      {dialog}
    </div>
  );
}

const blankResource = { url: "", title: "", level: "", format: "", hours: "", cost: "" };

/** One resource's fields — for a new one and for an edit. */
function AtlasResourceFields({ value, onChange }) {
  const set = (k) => (e) => onChange({ ...value, [k]: e.target.value });
  const pick = (k, list) => (
    <label style={label}>{k}
      <select value={value[k] ?? ""} onChange={set(k)} style={field}>{list.map(v => <option key={v} value={v}>{v || "—"}</option>)}</select>
    </label>
  );
  return (
    <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(130px, 1fr))", gap: 8 }}>
      <label style={{ ...label, gridColumn: "1 / -1" }}>Address (https only)<input type="url" value={value.url} onChange={set("url")} style={field} placeholder="https://…" /></label>
      <label style={{ ...label, gridColumn: "1 / -1" }}>Title<input value={value.title} onChange={set("title")} style={field} /></label>
      {pick("level", LEVELS)}{pick("format", FORMATS)}{pick("cost", COSTS)}
      <label style={label}>hours<input type="number" min="0" step="0.5" value={value.hours ?? ""} onChange={set("hours")} style={field} /></label>
    </div>
  );
}

/** The editor for one node: definition + Wikipedia title, typed edges, resources. */
function AtlasNodeEditor({ slug, say }) {
  const [n, setN] = useState(null);
  const [definition, setDefinition] = useState("");
  const [wikiTitle, setWikiTitle] = useState("");
  const [edge, setEdge] = useState({ to: "", type: "requires" });
  const [res, setRes] = useState(blankResource);
  const [editing, setEditing] = useState(null);   // { id, ...fields }
  const [busy, setBusy] = useState(false);
  const load = useCallback(() => api(`/api/admin/atlas/node/${enc(slug)}`).then(d => {
    setN(d); setDefinition(d.definition || ""); setWikiTitle(d.wikiTitle || "");
  }).catch(e => say({ ok: false, text: e.message })), [slug, say]);
  useEffect(() => { load(); }, [load]);
  const run = async (fn, okText) => {
    setBusy(true);
    try { await fn(); if (okText) say({ ok: true, text: okText }); await load(); }
    catch (e) { say({ ok: false, text: e.message }); }
    finally { setBusy(false); }
  };
  if (!n) return <p style={quiet}>Loading…</p>;
  const toFields = (r) => ({ id: r.id, url: r.url, title: r.title, level: r.level || "", format: r.format || "", hours: r.hours ?? "", cost: r.cost || "" });
  const removeEdge = (e) => (e.dir === "out"
    ? api(`/api/admin/atlas/node/${enc(slug)}/edges?to=${enc(e.slug)}&type=${enc(e.type)}`, { method: "DELETE" })
    : api(`/api/admin/atlas/node/${enc(e.slug)}/edges?to=${enc(slug)}&type=${enc(e.type)}`, { method: "DELETE" }));
  return (
    <div data-atlas-editor={slug} style={{ display: "grid", gap: 12, marginTop: 8, width: "100%" }}>
      <div style={{ display: "grid", gap: 6 }}>
        <label style={label}>Definition — in draft's own words (never Wikipedia's, never a model's)
          <textarea rows={3} value={definition} onChange={e => setDefinition(e.target.value)} style={{ ...field, height: "auto", padding: 8 }} data-atlas-definition="" />
        </label>
        <label style={label}>Wikipedia article title (its summary is shown as Wikipedia's, refreshed weekly; empty = none)
          <input value={wikiTitle} onChange={e => setWikiTitle(e.target.value)} style={field} placeholder="e.g. Kubernetes" data-atlas-wiki-title="" />
        </label>
        <div><DepthButton size="compact" primary disabled={busy} data-atlas-save=""
          onClick={() => run(() => send(`/api/admin/atlas/node/${enc(slug)}`, { definition, wikiTitle }, "PATCH"), `${n.name} saved.`)}>Save</DepthButton></div>
        {n.aliases?.length > 0 && <span style={quiet}>Aliases (skill_synonyms, confirmed): {n.aliases.join(", ")}</span>}
      </div>

      <div data-atlas-edges="" style={{ display: "grid", gap: 6 }}>
        <b style={{ fontSize: 12, color: C.INK }}>Edges</b>
        {n.edges.length === 0 && <span style={quiet}>None yet.</span>}
        {n.edges.map(e => (
          <div key={`${e.dir}:${e.type}:${e.slug}`} style={row}>
            <span style={{ fontSize: 12, color: C.INK, flex: "1 1 220px", overflowWrap: "anywhere" }}>
              {e.dir === "out" ? <>{n.name} <i>{e.type.replace(/_/g, " ")}</i> <b>{e.name}</b></> : <><b>{e.name}</b> <i>{e.type.replace(/_/g, " ")}</i> {n.name}</>}
              <span style={quiet}> · {e.source}{e.status !== "published" ? " · draft" : ""}</span>
            </span>
            <DepthButton size="compact" disabled={busy} data-atlas-edge-remove="" onClick={() => run(() => removeEdge(e), "Edge removed.")}>Remove</DepthButton>
          </div>
        ))}
        <div style={row}>
          <span style={{ fontSize: 12, color: C.INK_MUTED }}>{n.name}</span>
          <select aria-label="Edge type" value={edge.type} onChange={e => setEdge({ ...edge, type: e.target.value })} style={field}>
            {EDGE_TYPES.map(([v, l]) => <option key={v} value={v}>{l}</option>)}
          </select>
          <input aria-label="Edge target (slug)" placeholder="slug, e.g. docker" value={edge.to} onChange={e => setEdge({ ...edge, to: e.target.value })} style={{ ...field, flex: "1 1 140px" }} />
          <DepthButton size="compact" disabled={busy || !edge.to.trim()} data-atlas-edge-add=""
            onClick={() => run(async () => { await send(`/api/admin/atlas/node/${enc(slug)}/edges`, { to: edge.to.trim(), type: edge.type }); setEdge({ ...edge, to: "" }); }, "Edge added.")}>Add edge</DepthButton>
        </div>
      </div>

      <div data-atlas-resources="" style={{ display: "grid", gap: 8 }}>
        <b style={{ fontSize: 12, color: C.INK }}>Resources</b>
        {n.resources.length === 0 && <span style={quiet}>None yet.</span>}
        {n.resources.map(r => editing?.id === r.id ? (
          <div key={r.id} style={{ ...sub, display: "grid", gap: 8 }}>
            <AtlasResourceFields value={editing} onChange={setEditing} />
            <div style={row}>
              <DepthButton size="compact" primary disabled={busy} data-atlas-resource-save=""
                onClick={() => run(async () => { const { id, ...body } = editing; await send(`/api/admin/atlas/resources/${id}`, body, "PATCH"); setEditing(null); }, "Resource saved.")}>Save</DepthButton>
              <DepthButton size="compact" onClick={() => setEditing(null)}>Cancel</DepthButton>
            </div>
          </div>
        ) : (
          <div key={r.id} style={row} data-atlas-resource={r.id}>
            <span style={{ fontSize: 12, color: C.INK, flex: "1 1 220px", overflowWrap: "anywhere" }}>
              <a href={r.url} target="_blank" rel="noopener noreferrer" style={{ color: C.ACCENT_INK }}>{r.title}</a>
              <span style={quiet}> · {[r.level, r.format, r.hours != null ? `${r.hours} h` : null, r.cost].filter(Boolean).join(" · ") || "—"}</span>
            </span>
            {r.checkStatus && <Mark tone={STATUS_TONE[r.checkStatus] || C.INK_MUTED}>{r.checkStatus === "dead" ? "dead — hidden" : r.checkStatus}</Mark>}
            <DepthButton size="compact" disabled={busy} onClick={() => setEditing(toFields(r))} data-atlas-resource-edit="">Edit</DepthButton>
            <DepthButton size="compact" disabled={busy} data-atlas-resource-remove=""
              onClick={() => run(() => api(`/api/admin/atlas/resources/${r.id}`, { method: "DELETE" }), "Resource removed.")}>Remove</DepthButton>
          </div>
        ))}
        <div style={{ ...sub, display: "grid", gap: 8 }}>
          <AtlasResourceFields value={res} onChange={setRes} />
          <div><DepthButton size="compact" disabled={busy || !res.url.trim() || !res.title.trim()} data-atlas-resource-add=""
            onClick={() => run(async () => { await send(`/api/admin/atlas/node/${enc(slug)}/resources`, res); setRes(blankResource); }, "Resource added.")}>Add resource</DepthButton></div>
        </div>
      </div>
    </div>
  );
}

export function AtlasTab() {
  const [status, setStatus] = useState("draft");
  const [kind, setKind] = useState("");
  const [q, setQ] = useState("");
  const [rows, setRows] = useState(null);
  const [err, setErr] = useState(null);
  const [said, setSaid] = useState(null);
  const [busy, setBusy] = useState(null);
  const [open, setOpen] = useState(null);   // the slug whose editor is open (P6)

  const load = useCallback(() => {
    setErr(null);
    api(`/api/admin/atlas${status ? `?status=${status}` : ""}`).then(r => setRows(r.nodes || [])).catch(e => setErr(e.message));
  }, [status]);
  useEffect(() => { load(); }, [load]);

  const shown = useMemo(() => (rows || []).filter(r => (!kind || r.kind === kind)
    && (!q.trim() || r.name.toLowerCase().includes(q.trim().toLowerCase()))).slice(0, 200), [rows, kind, q]);

  const flip = async (r) => {
    const next = r.status === "published" ? "draft" : "published";
    setBusy(r.slug); setSaid(null);
    try {
      await api(`/api/admin/atlas/${encodeURIComponent(r.slug)}/status`, { method: "POST", body: JSON.stringify({ status: next }) });
      setSaid({ ok: true, text: `${r.name} is now ${next === "published" ? "PUBLISHED — anyone can open /atlas/" + r.slug : "a draft again — the public page is gone"}.` });
      // An unpublish by a person is recorded (it sticks); publishing again clears it — mirrored here until the next load.
      setRows(rs => (rs || []).map(x => x.slug === r.slug ? { ...x, status: next, publishedBy: next === "published" ? "you" : null,
        readiness: x.readiness ? { ...x.readiness, heldBy: next === "draft" ? "you" : null } : x.readiness } : x).filter(x => !status || x.status === status));
    } catch (e) { setSaid({ ok: false, text: e.message }); }
    finally { setBusy(null); }
  };

  const recompute = async () => {
    setBusy("stats"); setSaid(null);
    try { const r = await api("/api/admin/atlas/stats", { method: "POST" }); setSaid({ ok: true, text: `On the board recomputed — ${r.postings} active postings across ${r.nodes} nodes in ${r.ms} ms.` }); load(); }
    catch (e) { setSaid({ ok: false, text: e.message }); }
    finally { setBusy(null); }
  };

  // ⭐ P6: the dead-link checker and the Wikipedia refresh, now (both also run daily).
  const checkLinks = async () => {
    setBusy("links"); setSaid(null);
    try { const r = await api("/api/admin/atlas/links/check", { method: "POST" }); setSaid({ ok: true, text: `Links checked: ${r.checked} — ${r.ok} ok, ${r.failing} failing once, ${r.dead} dead (hidden after two failures in a row).` }); }
    catch (e) { setSaid({ ok: false, text: e.message }); }
    finally { setBusy(null); }
  };
  const refreshWiki = async () => {
    setBusy("wiki"); setSaid(null);
    try {
      const r = await api("/api/admin/atlas/wiki/refresh", { method: "POST" });
      const why = Object.entries(r.reasons || {}).map(([k, n]) => `${k} ×${n}`).join(", ");
      setSaid({ ok: !r.failed, text: `Wikipedia: ${r.fetched} of ${r.due} due summaries read${r.failed ? ` — ${r.failed} failed (${why})` : ""}${r.stoppedAt429 ? " — stopped at Wikipedia's rate limit; the rest tomorrow" : ""}.` });
    }
    catch (e) { setSaid({ ok: false, text: e.message }); }
    finally { setBusy(null); }
  };

  const runAuto = async () => {
    setBusy("auto"); setSaid(null);
    try {
      const r = await api("/api/admin/atlas/auto/run", { method: "POST" });
      // ⭐ BUG 10-31: the server's describeAutoRun line — each step's counters, and a failure named as an error.
      setSaid({ ok: !!r.ok, text: `Auto-publish: ${r.line}` });
      load();
    } catch (e) { setSaid({ ok: false, text: e.message }); }
    finally { setBusy(null); }
  };

  const askAgain = async () => {
    setBusy("ask"); setSaid(null);
    try { const r = await api("/api/admin/atlas/wiki/ask-again", { method: "POST" }); setSaid({ ok: true, text: `${r.cleared} unmatched node(s) will be asked again on the next run — press Run auto-publish now.` }); }
    catch (e) { setSaid({ ok: false, text: e.message }); }
    finally { setBusy(null); }
  };

  const counts = rows ? { total: rows.length, roles: rows.filter(r => r.kind === "role").length } : null;
  return (
    <Panel data-admin-atlas="" title="Atlas"
      purpose="The Atlas's pages. A draft publishes itself nightly once 5 active postings ask for it and it has a Wikipedia summary or a definition; each draft says what it is missing. Unpublishing here sticks — auto-publish never brings it back."
      code="D105 P4 + P6 · GET /api/admin/atlas · POST …/:slug/status · …/stats · …/nodes · …/merge · …/node/:slug (edges, resources) · …/resources/:id · …/links/check · …/wiki/refresh · public reads are published-only"
      numbers={counts ? [[counts.total, status ? `${status} nodes` : "nodes"], [counts.roles, "of them roles"]] : []}>
      <div style={{ ...row, marginBottom: 12 }}>
        <div role="group" aria-label="Status" style={row}>
          {[["draft", "Drafts"], ["published", "Published"], ["", "All"]].map(([v, l]) => (
            <DepthButton key={l} size="compact" pressed={status === v} onClick={() => setStatus(v)} data-atlas-status={v || "all"}>{l}</DepthButton>
          ))}
        </div>
        <select aria-label="Kind" value={kind} onChange={e => setKind(e.target.value)} style={field}>
          {KINDS.map(([v, l]) => <option key={l} value={v}>{l}</option>)}
        </select>
        <input aria-label="Filter by name" placeholder="Filter by name…" value={q} onChange={e => setQ(e.target.value)} style={{ ...field, flex: "1 1 180px" }} />
        <DepthButton size="compact" disabled={busy === "stats"} onClick={recompute} data-atlas-recompute="">Recompute On the board</DepthButton>
        <DepthButton size="compact" disabled={busy === "links"} onClick={checkLinks} data-atlas-check-links="">Check links now</DepthButton>
        <DepthButton size="compact" disabled={busy === "wiki"} onClick={refreshWiki} data-atlas-refresh-wiki="">Refresh Wikipedia</DepthButton>
        <DepthButton size="compact" disabled={busy === "auto"} onClick={runAuto} data-atlas-run-auto="">Run auto-publish now</DepthButton>
        <DepthButton size="compact" disabled={busy === "ask"} onClick={askAgain} data-atlas-ask-again="">Ask Wikipedia again</DepthButton>
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(260px, 1fr))", gap: 10, marginBottom: 12 }}>
        <AtlasAddNode say={setSaid} onAdded={(node) => { load(); setOpen(node.slug); }} />
        <AtlasMerge say={setSaid} onMerged={(r) => { setRows(rs => (rs || []).filter(x => x.slug !== r.loser)); setOpen(o => (o === r.loser ? r.winner : o)); }} />
      </div>
      {said && <div role="status" style={{ ...callout(said.ok ? C.SUCCESS : C.DANGER), marginBottom: 10 }}>{said.text}</div>}
      {err && <div style={{ ...callout(C.DANGER), marginBottom: 10 }}>{err}</div>}
      {!rows ? <p style={quiet}>Loading…</p> : shown.length === 0 ? <p style={quiet}>No node matches.</p> : (
        <div style={{ display: "grid", gap: 6 }}>
          {shown.map(r => (
            <div key={r.slug} data-atlas-row={r.slug} style={{ ...sub, display: "flex", gap: 10, alignItems: "center", flexWrap: "wrap" }}>
              <span style={{ flex: "1 1 200px", fontSize: 13, color: C.INK, overflowWrap: "anywhere" }}>
                <b>{r.name}</b> <span style={quiet}>{r.kind} · {r.postings} posting{r.postings === 1 ? "" : "s"} · {r.source}</span>
                {readinessLine(r) && <span style={{ ...quiet, display: "block" }} data-atlas-readiness={r.readiness?.ready ? "ready" : "not-ready"}>{readinessLine(r)}</span>}
              </span>
              <Mark tone={r.status === "published" ? C.SUCCESS : C.INK_MUTED}>{r.status}</Mark>
              {r.status === "published" && <a href={`/atlas/${encodeURIComponent(r.slug)}`} target="_blank" rel="noopener noreferrer" style={{ fontSize: 12, color: C.ACCENT_INK }}>Open page</a>}
              <DepthButton size="compact" primary={r.status !== "published"} disabled={busy === r.slug} onClick={() => flip(r)} data-atlas-flip={r.slug}>
                {r.status === "published" ? "Unpublish" : "Publish"}
              </DepthButton>
              <DepthButton size="compact" pressed={open === r.slug} onClick={() => setOpen(o => (o === r.slug ? null : r.slug))} data-atlas-edit={r.slug}>
                {open === r.slug ? "Close" : "Edit"}
              </DepthButton>
              {open === r.slug && <AtlasNodeEditor slug={r.slug} say={setSaid} />}
            </div>
          ))}
          {(rows.length > shown.length) && <p style={quiet}>Showing {shown.length} of {rows.length} — filter to find the rest.</p>}
        </div>
      )}
    </Panel>
  );
}
